entries[63039] = { ["name"] = "Reins of the Drake of the West Wind", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Baradin's Wardens\n- Exalted\n\n\"Harnessing the elemental powers of the storm, these majestic beasts crackle like lightning and roar like thunder.\"\nVendor:\nQuartermaster Brazie\nZone:\nTol Barad Peninsula\nFaction:\nBaradin's Wardens - Exalted" }
entries[63040] = { ["name"] = "Reins of the Drake of the North Wind", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"They sicken of the calm who know the storm.\"\nDrop:\nAltairus\nZone:\nThe Vortex Pinnacle" }
entries[63041] = { ["name"] = "Reins of the Drake of the South Wind", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Gentle as a summer breeze, but that says little considering where it came from. -Itesh\"\nDrop:\nAl'Akir\nZone:\nThrone of the Four Winds" }
entries[63042] = { ["name"] = "Reins of the Phosphorescent Stone Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The Stonemother has shown little concern for the rebellious Aeonaxx, even allowing his spawn to be taken from her realm.\"\nDrop:\nAeonaxx\nLocation:\nDeepholm" }
entries[63043] = { ["name"] = "Reins of the Vitreous Stone Drake", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Those would be perfect in a pendant, and that would make a fantastic ring. Let me know if this thing sheds or molts or whatever. -Kalinda\"\nDrop:\nSlabhide\nZone:\nThe Stonecore" }
